
import Vue from 'vue';
export default Vue.extend({
  props: {
    index: Number,
    img: Object
  },
  methods: {
    updateX(x) {
      this.img.set('left', parseInt(x))
      this.updateCanvas();
    },
    updateY(y) {
      this.img.set('top', parseInt(y))
      this.updateCanvas();
    },
    updateCanvas() {
      this.img.setCoords();
      (document.getElementById('can') as any).fabric.renderAll();
    }
  }
})
