
import Vue from 'vue';
import Utils from "../../../utils"
export default Vue.extend({
  props: {
    value: Boolean,
  },
  computed: {
    show: {
      get() {
        return this.value;
      },
      set(value) {
        this.$emit("input", value);
      },
    },
  },
  methods: {
    getVuejsSVG() {
      return Utils.getRoot() + 'img/icons/vuejs.svg';
    },
    getVuetifySVG() {
      return Utils.getRoot() + 'img/icons/vuetify.svg';
    },
  }
});
