
import Vue from 'vue';
import OptionTitle from '../ui/OptionTitle.vue';
export default Vue.extend({
  components: { OptionTitle },
  props: {
    player: Object,
    title: String,
  },
  data() {
    return {
      activeV: 1,
      activeH: 1,
    };
  },
  methods: {
    reset() {
      let text = this.player.myTag ? this.player.myTag : this.player;
      text.reset();
      
      this.player.align('center', 'middle');
      // TODO a modifier
      if (this.title === "Versus") {
        text.text.center();
      }
    }
  }
});
